<?php
require 'includes/auth_helpers.php'; require 'includes/db.php';
$role=current_role($pdo);
if($role==='staff'){http_response_code(403);exit('Staff accounts cannot submit customer contact requests.');}
$errors=[];$saved=false;
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!csrf_check($_POST['csrf']??null))$errors[]='Your session expired. Please try again.';
 $n=trim((string)($_POST['full_name']??''));$email=strtolower(trim((string)($_POST['email']??'')));$mobile=trim((string)($_POST['mobile_number']??''));$subject=trim((string)($_POST['subject']??''));$message=trim((string)($_POST['message']??''));
 if(!$n||!filter_var($email,FILTER_VALIDATE_EMAIL)||!$mobile||!$subject||mb_strlen($message)<5)$errors[]='Please complete each field and enter a valid email.';
 if(!$errors&&email_owned_by_another_account($pdo,$email))$errors[]='That email address belongs to another account. Use your own email address.';
 if(!$errors){$pdo->prepare('INSERT INTO contact_submissions(full_name,email,mobile_number,subject,message) VALUES(?,?,?,?,?)')->execute([$n,$email,$mobile,$subject,$message]);$id=(int)$pdo->lastInsertId();$pdo->prepare("INSERT INTO team_inbox_events(event_type,title,message,audience,entity_type,entity_id) VALUES('customer_feedback','New customer feedback',?,'all','contact',?)")->execute([$subject.' — '.$n,$id]);$saved=true;}
}
$pageTitle='Contact Us';require 'includes/header.php'; ?>
<main class="container py-5"><div class="form-panel mx-auto" style="max-width:800px"><h1 class="text-center mb-2">Contact Nomcha</h1><p class="text-center text-secondary mb-4">Questions, feedback, and concerns go straight to our team inbox.</p><?php if($saved):?><div class="alert alert-success">Thanks for reaching out. Your message is with our team.</div><?php endif;?><?php foreach($errors as $er):?><div class="alert alert-danger"><?=e($er)?></div><?php endforeach;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="mb-3"><label class="form-label">Full name *</label><input class="form-control" name="full_name" required></div><div class="row"><div class="col-md-6 mb-3"><label class="form-label">Email address *</label><input class="form-control" type="email" name="email" required></div><div class="col-md-6 mb-3"><label class="form-label">Contact number *</label><input class="form-control" name="mobile_number" placeholder="09XX XXX XXXX" required></div></div><div class="mb-3"><label class="form-label">Subject *</label><select class="form-select" name="subject" required><option value="">Choose a subject</option><?php foreach(['General inquiry','Order issue','Product feedback','Compliment','Allergy or food safety','Careers','Other'] as $s):?><option><?=e($s)?></option><?php endforeach;?></select></div><div class="mb-4"><label class="form-label">Message *</label><textarea class="form-control" rows="6" name="message" required></textarea></div><button class="btn btn-order d-block mx-auto" type="submit">Send message</button></form></div></main><?php require 'includes/footer.php'; ?>
